using System.Windows; using BioVic.Desktop.Services;
namespace BioVic.Desktop.Views;
public partial class FailureWindow:Window{private readonly BioVicApiClient _client;private readonly Guid _id;public FailureWindow(BioVicApiClient client,Guid id){InitializeComponent();_client=client;_id=id;DateBox.SelectedDate=DateTime.Today;}private async void Save_Click(object s,RoutedEventArgs e){try{int? downtime=null;if(!string.IsNullOrWhiteSpace(DowntimeBox.Text)){if(!int.TryParse(DowntimeBox.Text,out var n)||n<0)throw new BioVicApiException("El tiempo debe ser un número positivo.");downtime=n;}await _client.AddFailureAsync(_id,new(ToUtc(DateBox.SelectedDate)??DateTimeOffset.UtcNow,DescriptionBox.Text,ReportedByBox.Text,ServiceBox.Text,ImpactBox.Text,StoppedBox.IsChecked==true,ImmediateBox.Text,DiagnosisBox.Text,SolutionBox.Text,downtime,ToUtc(ClosedBox.SelectedDate)));DialogResult=true;}catch(Exception ex){ErrorText.Text=ex.Message;}}private static DateTimeOffset? ToUtc(DateTime? d)=>d is null?null:new DateTimeOffset(d.Value).ToUniversalTime();private void Cancel_Click(object s,RoutedEventArgs e)=>DialogResult=false;}
